import {allocation,opportunity,marginal} from './analysis-models.js';
const nf=new Intl.NumberFormat('es-CO',{maximumFractionDigits:2});
const f=n=>nf.format(n);
const defaults={scarcity:{hours:120,a:2,b:4,x:30,y:15},opportunity:{income:900,cost:300,hours:20,wage:20,alternative:500},marginal:{price:100,first:40,step:10,fixed:200,q:4}};
const state=structuredClone(defaults),saved={},notes={};
const input=(group,key,label,min,max,step=1)=>`<label class="experiment-control" for="${group}-${key}"><span>${label} <output id="${group}-${key}-value"></output></span><input type="range" id="${group}-${key}" data-group="${group}" data-key="${key}" min="${min}" max="${max}" step="${step}" value="${state[group][key]}"></label>`;
const writing=(id,label)=>`<label class="experiment-note" for="note-${id}">${label}<textarea id="note-${id}" data-note="${id}" rows="3"></textarea></label>`;
const actions=id=>`<div class="experiment-actions"><button class="btn" data-save="${id}">Guardar escenario para comparar</button><button class="btn secondary" data-reset="${id}">Restablecer variables</button></div><p id="comparison-${id}" class="comparison" role="status"></p>`;
const checkpoint=(id,prompt,answer,explanation)=>`<form class="experiment-check" data-answer="${answer}" data-explanation="${explanation}"><label for="check-${id}"><strong>Comprueba tu razonamiento</strong><br>${prompt}</label><div><input id="check-${id}" type="number" step="any" required><button class="btn" type="submit">Comprobar</button></div><p role="status"></p></form>`;
export function analysisPage(){return `<header class="hero"><span class="index">TALLER INTERACTIVO · SESIONES 2, 3 Y 4</span><h1>¿Qué cambia si…?</h1><p class="lead">Tres decisiones de una empresa exportadora. Predice, cambia una variable, compara y construye una explicación con evidencia.</p><span class="tag sim">Todos los valores de estos ejercicios son simulados</span></header>
<div class="steps"><div class="step"><h3>1. Predice</h3><p>Escribe qué esperas que ocurra antes de mover los controles.</p></div><div class="step"><h3>2. Experimenta</h3><p>Guarda un escenario y modifica una sola variable para aislar su efecto.</p></div><div class="step"><h3>3. Argumenta</h3><p>Usa cifras, unidades, un concepto y un límite del modelo.</p></div></div>
<section class="experiment"><span class="tag">01 · Escasez y frontera de producción</span><h2>Un taller, dos productos, tiempo limitado.</h2><p>Una cooperativa prepara lotes de cacao y chocolate para exportar. Decide cuántos lotes solicitar con las horas disponibles. Puedes ensayar incluso un pedido imposible.</p>${writing('scarcity-prediction','Antes de empezar: si duplicas las horas, ¿cambia el costo de oportunidad de un lote de chocolate?')}
<div class="experiment-grid"><div>${input('scarcity','hours','Horas disponibles (h)',40,240,10)}${input('scarcity','a','Horas por lote de cacao',1,8)}${input('scarcity','b','Horas por lote de chocolate',1,12)}${input('scarcity','x','Lotes de cacao solicitados',0,120)}${input('scarcity','y','Lotes de chocolate solicitados',0,80)}</div><div><div id="scarcity-chart"></div><div id="scarcity-result" class="experiment-result" role="status"></div></div></div>${actions('scarcity')}
<details><summary>Ver las relaciones del modelo</summary><p>Horas usadas = horas por cacao × lotes de cacao + horas por chocolate × lotes de chocolate. Una combinación es factible si no supera las horas disponibles. El costo de oportunidad de 1 chocolate = horas por chocolate ÷ horas por cacao, medido en lotes de cacao.</p><p>Supuestos: trabajo como único recurso, productividad constante, lotes divisibles sobre la frontera y sin costos de transporte. Los controles eligen lotes enteros. Tener horas libres no elimina la escasez; señala capacidad sin utilizar en este modelo.</p></details>
<ol><li>Con los valores iniciales, sube el pedido de chocolate de 15 a 20. ¿Cuántas horas faltan?</li><li>Vuelve al inicio y aumenta solo las horas a 240. Compara capacidad y pendiente.</li><li>Vuelve al inicio y reduce solo las horas por chocolate de 4 a 2. Explica por qué cambia el sacrificio de cacao.</li></ol>${checkpoint('scarcity','Con 120 horas, 2 h por cacao, 4 h por chocolate y un pedido de 30 cacao y 20 chocolate, ¿cuántas horas faltan?',20,'Se requieren 30 × 2 + 20 × 4 = 140 h. Faltan 20 h. Puedes reducir 5 chocolates o 10 cacaos para volver a la frontera.')}${writing('scarcity-conclusion','Conclusión: distingue un aumento de recursos de una mejora de productividad.')}<a href="#lecturas">Conecta con Shah, Mullainathan y Shafir; y el caso del Canal de Panamá →</a></section>
<section class="experiment"><span class="tag">02 · Costo de oportunidad</span><h2>¿Aceptar un proyecto de exportación?</h2><p>Tienes un bloque de tiempo y tres opciones excluyentes: preparar una exportación, trabajar por horas o realizar otro proyecto. Todos los importes están en <strong>miles de COP</strong>. Los ingresos y costos se refieren al mismo bloque de tiempo.</p>${writing('opportunity-prediction','Predice: si el proyecto deja dinero después de pagar sus gastos, ¿siempre conviene aceptarlo?')}
<div class="experiment-grid"><div>${input('opportunity','income','Ingreso del proyecto (miles de COP)',0,2000,50)}${input('opportunity','cost','Gastos explícitos (miles de COP)',0,1000,50)}${input('opportunity','hours','Tiempo comprometido (h)',5,40,5)}${input('opportunity','wage','Pago neto alternativo por hora (miles de COP/h)',0,60,5)}${input('opportunity','alternative','Ingreso neto del otro proyecto (miles de COP)',0,1500,50)}</div><div id="opportunity-result" class="experiment-result" role="status"></div></div>${actions('opportunity')}
<details><summary>¿Por qué no se suman las alternativas?</summary><p>Ingreso neto del proyecto = ingreso − gastos explícitos. Costo de oportunidad = máximo entre pago por horas y beneficio neto del otro proyecto. Ventaja económica = ingreso neto del proyecto − mejor alternativa. No puedes hacer las dos alternativas a la vez: sumar sus ingresos sobreestimaría lo sacrificado.</p><p>Supuestos: ingresos ciertos y comparables, igual horizonte, alternativas mutuamente excluyentes; no se valoran aprendizaje, ocio, riesgo ni preferencias. El resultado compara dinero, no decide por ti.</p></details><ol><li>Con los valores iniciales, aumenta solo el pago por hora a 35. ¿Cambia la mejor alternativa y la recomendación monetaria?</li><li>Encuentra el pago por hora que hace indiferente el proyecto y el trabajo, manteniendo todo lo demás inicial.</li><li>Propón un beneficio no monetario que podría cambiar tu elección.</li></ol>${checkpoint('opportunity','Con los valores iniciales, ¿cuál es el costo de oportunidad en miles de COP?',500,'El trabajo ofrece 20 × 20 = 400; el otro proyecto, 500. Se sacrifica la mejor alternativa: 500, no la suma 900. El proyecto elegido deja 600; su ventaja económica es 100.')}${writing('opportunity-conclusion','Conclusión: identifica la mejor alternativa que sacrificas y explica el cambio.')}<a href="#lecturas">Conecta con Opportunity Cost Neglect →</a></section>
<section class="experiment"><span class="tag">03 · Cambios marginales</span><h2>¿Conviene enviar una caja más?</h2><p>Una empresa vende cajas a un precio constante. Las primeras son más baratas de preparar; cada caja adicional exige recursos más costosos. Cambia precio, costos y cantidad. Valores en <strong>miles de COP</strong>.</p>${writing('marginal-prediction','Predice: si aumenta un gasto ya pagado e irrecuperable, ¿cambia la cantidad que más conviene producir hoy?')}
<div class="experiment-grid"><div>${input('marginal','price','Precio por caja (miles de COP)',20,200,10)}${input('marginal','first','Costo de la primera caja (miles de COP)',10,100,10)}${input('marginal','step','Aumento del costo por caja adicional (miles de COP)',0,20,5)}${input('marginal','fixed','Gasto ya pagado e irrecuperable (miles de COP)',0,1000,50)}${input('marginal','q','Cajas que decides producir',0,20)}</div><div><div id="marginal-chart"></div><div id="marginal-result" class="experiment-result" role="status"></div></div></div>${actions('marginal')}
<details><summary>Ver cálculo y tabla de las 21 alternativas</summary><p>CM de la caja n = costo de la primera + aumento × (n − 1). Ingreso marginal = precio. Cambio de beneficio al agregar una caja = precio − CM de esa caja. Beneficio total = precio × cantidad − gasto ya pagado − suma de costos de las cajas.</p><p>El gasto pagado se conserva incluso con cero producción. Solo bajo este supuesto no cambia la cantidad óptima. Un costo fijo evitable al cerrar podría cambiar la decisión. No hay inventarios, incertidumbre ni efectos del precio sobre la demanda; capacidad máxima de 20 cajas.</p><div id="marginal-table" class="experiment-table"></div></details>
<ol><li>Con los valores iniciales, pasa de 4 a 5 cajas y luego de 7 a 8. Compara el cambio de beneficio.</li><li>Sube solo el gasto ya pagado de 200 a 800. ¿Qué pasa con el beneficio y con las cantidades óptimas?</li><li>Sube solo el precio. Explica por qué ahora pueden convenir más cajas.</li></ol>${checkpoint('marginal','Con precio 100, primera caja 40 y aumento 10, ¿cuánto cambia el beneficio al pasar de 7 a 8 cajas? Usa un número negativo si disminuye.',-10,'La octava caja cuesta 40 + 10 × 7 = 110 y aporta 100. El beneficio disminuye 10. La séptima cuesta 100: por eso 6 y 7 cajas empatan en el máximo con estos valores.')}${writing('marginal-conclusion','Conclusión: compara costo marginal, ingreso marginal y beneficio total.')}<a href="#lecturas">Conecta con la investigación sobre fertilizantes y decisiones →</a></section>
<section class="section"><h2>Tu bitácora de análisis</h2><p>Las notas y variables se conservan al cambiar de sección mientras esta página siga abierta. Descarga tu trabajo antes de cerrar o recargar. No se envía automáticamente a la docente.</p>${writing('synthesis','Integra: ¿qué predicción cambiaste y qué evidencia te hizo cambiar? Cita una lectura y señala un límite de tu conclusión.')}<button class="btn" id="download-analysis">Descargar mi bitácora (.txt)</button><p id="analysis-download-status" role="status"></p></section>`;}

function scarcityChart(s,r){const maxX=Math.max(r.maxX,s.x,1)*1.1,maxY=Math.max(r.maxY,s.y,1)*1.1;const x=n=>60+400*n/maxX,y=n=>255-205*n/maxY;return `<svg viewBox="0 0 520 305" role="img" aria-label="Frontera: máximo ${f(r.maxX)} cacaos o ${f(r.maxY)} chocolates. Pedido ${r.feasible?'factible':'inviable'}."><path d="M60 35V255H475" fill="none" stroke="#636363"/><path d="M60 255 L60 ${y(r.maxY)} L${x(r.maxX)} 255Z" fill="#f0dddd"/><path d="M60 ${y(r.maxY)}L${x(r.maxX)} 255" stroke="#841F1C" stroke-width="3"/><circle cx="${x(s.x)}" cy="${y(s.y)}" r="7" fill="#C20E1A" stroke="white" stroke-width="2"/><text x="60" y="20">Chocolate (lotes)</text><text x="340" y="295">Cacao (lotes)</text><text x="8" y="${y(r.maxY)+5}">${f(r.maxY)}</text><text x="${x(r.maxX)-10}" y="275">${f(r.maxX)}</text><text x="40" y="274">0</text></svg><p class="caption">Línea: frontera. Área: combinaciones factibles. Punto: pedido. Los ejes se ajustan al escenario.</p>`;}
function marginalChart(s,r){const ymax=Math.max(s.price,s.first+19*s.step,1)*1.15;const y=n=>245-210*n/ymax,x=n=>55+21*n;return `<svg viewBox="0 0 525 300" role="img" aria-label="Ingreso marginal constante ${s.price}. Costo marginal de la primera caja ${s.first} y de la última ${s.first+19*s.step}. Cantidades óptimas ${r.optima.join(', ')}."><path d="M55 25V245H490" stroke="#636363" fill="none"/><path d="M${x(1)} ${y(s.first)}L${x(20)} ${y(s.first+19*s.step)}" stroke="#841F1C" stroke-width="3"/><path d="M55 ${y(s.price)}H480" stroke="#636363" stroke-width="3" stroke-dasharray="7 4"/><text x="55" y="18">Miles de COP por caja</text><text x="360" y="285">Número de caja</text><text x="20" y="${y(s.price)}">${s.price}</text>${[1,5,10,15,20].map(n=>`<text x="${x(n)-5}" y="265">${n}</text>`).join('')}${s.q?`<circle cx="${x(s.q)}" cy="${y(r.mc)}" r="6" fill="#C20E1A"/>`:''}</svg><p class="caption">Línea continua: costo marginal. Discontinua: ingreso marginal. Punto: última caja de tu elección. Consulta los valores exactos en la tabla.</p>`;}
function result(group){const s=state[group];return group==='scarcity'?allocation(s):group==='opportunity'?opportunity(s):marginal(s);}
function summary(group,s){const r=group==='scarcity'?allocation(s):group==='opportunity'?opportunity(s):marginal(s);return group==='scarcity'?`Horas usadas: ${f(r.used)}; saldo: ${f(r.slack)} h; costo de oportunidad: ${f(r.opportunity)} cacao/chocolate.`:group==='opportunity'?`Neto: ${f(r.net)}; costo de oportunidad: ${f(r.best)}; ventaja económica: ${f(r.economic)} (miles de COP).`:`Cantidad: ${s.q}; beneficio: ${f(r.profit)}; óptimos: ${r.optima.join(', ')} cajas; máximo: ${f(r.best)} (miles de COP).`;}
function update(group){const s=state[group],r=result(group);document.querySelectorAll(`[data-group="${group}"]`).forEach(el=>{el.value=s[el.dataset.key];document.getElementById(el.id+'-value').textContent=f(s[el.dataset.key]);});
  if(group==='scarcity'){document.getElementById('scarcity-chart').innerHTML=scarcityChart(s,r);document.getElementById('scarcity-result').innerHTML=`<h3>${r.slack<0?'Pedido imposible':r.slack===0?'En la frontera':'Dentro de la frontera'}</h3><p>Usas <strong>${f(r.used)} de ${s.hours} h</strong>. ${r.slack<0?`Faltan ${f(-r.slack)} h.`:`Quedan ${f(r.slack)} h disponibles.`}</p><p>Un chocolate adicional sacrifica <strong>${f(r.opportunity)} lotes de cacao</strong> cuando estás en la frontera. ${r.slack>0?'Antes puedes usar las horas libres.':''}</p>`;}
  if(group==='opportunity')document.getElementById('opportunity-result').innerHTML=`<h3>${r.economic>0?'El proyecto supera la mejor alternativa':r.economic<0?'La mejor alternativa deja más dinero':'Indiferencia monetaria'}</h3><p>Neto del proyecto: <strong>${f(r.net)}</strong></p><p>Trabajo: ${f(r.job)} · Otro proyecto: ${f(s.alternative)}</p><p>Costo de oportunidad: <strong>${f(r.best)}</strong><br>${r.choice}</p><p>Ventaja económica: <strong>${f(r.economic)}</strong> miles de COP</p><p>No sumes alternativas excluyentes ni vuelvas a descontar los gastos explícitos del ingreso neto.</p>`;
  if(group==='marginal'){document.getElementById('marginal-chart').innerHTML=marginalChart(s,r);document.getElementById('marginal-result').innerHTML=`<h3>${r.next===null?'Alcanzaste la capacidad':s.price>r.next?'Una caja más aumenta el beneficio':s.price===r.next?'Una caja más deja el mismo beneficio':'Una caja más reduce el beneficio'}</h3><p>Beneficio con ${s.q} cajas: <strong>${f(r.profit)}</strong> miles de COP.</p><p>${r.next===null?'Máximo de 20 cajas.':`Siguiente caja: ingreso ${s.price} − costo ${f(r.next)} = <strong>${f(s.price-r.next)}</strong>.`}</p><p>Cantidad${r.optima.length>1?'es':''} que maximiza${r.optima.length>1?'n':''} el beneficio: <strong>${r.optima.join(', ')} cajas</strong>. Beneficio máximo: ${f(r.best)}.</p>${r.best<0?'<p>El máximo sigue siendo negativo: maximizar aquí significa minimizar la pérdida, dado el gasto irrecuperable.</p>':''}`;document.getElementById('marginal-table').innerHTML=`<table><caption>Alternativas: miles de COP; CM de la última caja</caption><thead><tr><th>Cajas</th><th>Ingreso total</th><th>Costo total</th><th>CM</th><th>Beneficio</th></tr></thead><tbody>${r.rows.map(row=>`<tr ${r.optima.includes(row.q)?'class="optimal"':''}><th>${row.q}${r.optima.includes(row.q)?' ★':''}</th><td>${f(row.revenue)}</td><td>${f(row.cost)}</td><td>${row.mc===null?'—':f(row.mc)}</td><td>${f(row.profit)}</td></tr>`).join('')}</tbody></table>`;}
  document.getElementById('comparison-'+group).textContent=saved[group]?`Guardado → ${summary(group,saved[group])} Actual → ${summary(group,s)}`:'Guarda este escenario antes de cambiar una variable.';
}
export function bindAnalysis(){Object.keys(state).forEach(update);document.querySelectorAll('[data-group]').forEach(el=>el.addEventListener('input',()=>{state[el.dataset.group][el.dataset.key]=Number(el.value);update(el.dataset.group);}));document.querySelectorAll('[data-note]').forEach(el=>{el.value=notes[el.dataset.note]||'';el.addEventListener('input',()=>{notes[el.dataset.note]=el.value;});});document.querySelectorAll('[data-save]').forEach(el=>el.addEventListener('click',()=>{saved[el.dataset.save]=structuredClone(state[el.dataset.save]);update(el.dataset.save);}));document.querySelectorAll('[data-reset]').forEach(el=>el.addEventListener('click',()=>{state[el.dataset.reset]=structuredClone(defaults[el.dataset.reset]);update(el.dataset.reset);}));document.querySelectorAll('.experiment-check').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const correct=Math.abs(Number(form.querySelector('input').value)-Number(form.dataset.answer))<0.001;form.querySelector('p').textContent=(correct?'Correcto. ':'Revisa el cálculo. ')+form.dataset.explanation;}));document.getElementById('download-analysis').addEventListener('click',()=>{const text='BITÁCORA · LABORATORIO DE ECONOMÍA Y COMERCIO\nValores simulados. Importes monetarios en miles de COP.\n'+Object.keys(state).map(g=>`\n${g.toUpperCase()}\nVariables actuales: ${JSON.stringify(state[g])}\n${summary(g,state[g])}\nEscenario guardado: ${saved[g]?JSON.stringify(saved[g])+'\n'+summary(g,saved[g]):'Sin guardar'}`).join('\n')+'\n\nMIS NOTAS\n'+Object.entries(notes).map(([k,v])=>k+'\n'+v).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='bitacora-analisis-economico.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('analysis-download-status').textContent='Bitácora lista para descargar.';});}
